import{_ as a}from"./chunks/ilabs-ins-u.C5gOsaLP.js";import{_ as r,o as t,c as o,al as i}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"Inertial Labs INS (All sensors, including INS-U/INS-DU)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sensor/inertiallabs.md","filePath":"uk/sensor/inertiallabs.md"}'),n={name:"uk/sensor/inertiallabs.md"};function s(l,e,c,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="inertial-labs-ins-all-sensors-including-ins-u-ins-du" tabindex="-1">Inertial Labs INS (All sensors, including INS-U/INS-DU) <a class="header-anchor" href="#inertial-labs-ins-all-sensors-including-ins-u-ins-du" aria-label="Permalink to &quot;Inertial Labs INS (All sensors, including INS-U/INS-DU)&quot;">​</a></h1><p>Inertial Labs designs and develops <a href="https://inertiallabs.com/products/imu-inertial-measurement-units/" target="_blank" rel="noreferrer">IMU</a>, <a href="https://inertiallabs.com/products/ahrs/" target="_blank" rel="noreferrer">AHRS</a>, <a href="https://inertiallabs.com/products/ins-inertial-navigation-systems/" target="_blank" rel="noreferrer">GNSS/INS</a> and <a href="https://inertiallabs.com/" target="_blank" rel="noreferrer">other</a> solutions. A universal protocol is used for <a href="https://inertiallabs.com/" target="_blank" rel="noreferrer">all Inertial Labs sensors</a>.</p><p><img src="'+a+`" alt="INS-U"></p><p>Benefits to PX4 users:</p><ul><li>Вища точність оцінки напрямку, крену та кочення</li><li>Більш надійна геоприв&#39;язка GNSS</li><li>Покращена точність позиціонування та установки під час конфлікту супутникового зв&#39;язку</li><li>Продуктивність при динамічних умовах (наприклад, запуски катапультою, операції VTOL, високі g або високі операції з великою кутовою швидкістю)</li><li>Work in different spoofing and jamming conditions</li></ul><p>PX4 can use these in a mode that provides only raw sensor output (the default), or as an <a href="./../sensor/inertial_navigation_systems">external INS</a> that provides both sensor output and INS data such as position and velocity estimates. The mode is configurable using a parameter.</p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p><a href="https://inertiallabs.com/inertial-labs-inc/contact-inertial-labs-team/" target="_blank" rel="noreferrer">Get technical support or send requests to sales team</a>. Recommended sensors:</p><ul><li><a href="https://inertiallabs.com/wp-content/uploads/2026/01/INS-U_INS-U-OEM_Datasheet_REV2.18_JAN2026.pdf" target="_blank" rel="noreferrer">INS-U GNSS/INS</a>: Recommended for fixed-wing systems without hovering, where static heading is not necessary.</li><li><a href="https://inertiallabs.com/wp-content/uploads/2025/12/INS-DU_INS-DU-OEM_Datasheet_REV1.00_DEC2025.pdf" target="_blank" rel="noreferrer">INS-DU DUAL GNSS/INS</a>: Recommended for multicopter systems where hovering and low dynamics requires the use of static heading.</li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>Connect the sensor to any unused flight controller serial interface, such as a spare <code>GPS</code> or <code>TELEM</code>.</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The Inertial Labs sensors can be mounted in any orientation. You can set offsets for coordinate axes in the sensor-configuration software that is provided with your sensor.</p><h2 id="конфігурація-прошивки" tabindex="-1">Конфігурація прошивки <a class="header-anchor" href="#конфігурація-прошивки" aria-label="Permalink to &quot;Конфігурація прошивки&quot;">​</a></h2><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>To use the Inertial Labs driver:</p><ol><li>Build the firmware with the <a href="./../modules/modules_driver_ins#ilabs">ilabs</a> module. <ul><li><p>Make sure the UART RX-buffer for the serial port connected to the INS is at least <strong>600 bytes</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For example, when using <code>TELEM2</code> on Pixhawk 6X, add the following setting to <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6x/nuttx-config/nsh/defconfig" target="_blank" rel="noreferrer">defconfig</a>: <code>CONFIG_UART5_RXBUFSIZE=600</code></p><p>Note that the mapping between UART number and port name can usually be found in your board&#39;s <a href="./../flight_controller/pixhawk6x#serial-port-mapping">Serial Port Mapping</a> section.</p></div></li></ul></li></ol><p>:::</p><ul><li>Include the module in firmware in the <a href="./../hardware/porting_guide_config#px4-board-configuration-kconfig">kconfig board configuration</a> by setting the kconfig variables: <code>CONFIG_DRIVERS_INS_ILABS</code>. In the kconfig interface: Drivers -&gt; INS -&gt; ilabs.</li></ul><ol start="2"><li><p><a href="./../advanced_config/parameters">Set the parameter</a> <a href="./../advanced_config/parameter_reference#SENS_ILABS_CFG">SENS_ILABS_CFG</a> to the hardware port connected to the sensor, such as a spare <code>GPS</code> or <code>TELEM</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Disable or change port of other sensors that are using the same one, for example <a href="./../advanced_config/parameter_reference#GPS_1_CONFIG">GPS_1_CONFIG</a> if using GPS1 port.</p></div></li></ol><p>:::</p><ol start="3"><li><p>Allow the Inerital Labs driver to initialize by restarting PX4.</p></li><li><p>Configure driver to provide IMU data or Raw sensors data :</p><ul><li><p>For external INS, set <a href="./../advanced_config/parameter_reference#ILABS_MODE">ILABS_MODE</a> to <code>INS</code>.</p><p>In this case, the <a href="./../advanced_config/parameter_reference#EKF2_EN">EKF2_EN</a>, <a href="./../advanced_config/parameter_reference#SENS_IMU_MODE">SENS_IMU_MODE</a>, and <a href="./../advanced_config/parameter_reference#SENS_MAG_MODE">SENS_MAG_MODE</a> parameters are disabled at startup (set to <code>0</code>). Аnd the INS&#39;s internal EKF is used for orientation.</p></li><li><p>For raw inertial sensors, set <a href="./../advanced_config/parameter_reference#ILABS_MODE">ILABS_MODE</a> to <code>Sensors Only</code>.</p><p>Prioritize Inertial Labs sensors using <a href="./../advanced_config/parameter_reference#CAL_GYRO0_PRIO">CAL_GYROn_PRIO</a>, <a href="./../advanced_config/parameter_reference#CAL_ACC0_PRIO">CAL_ACCn_PRIO</a>, <a href="./../advanced_config/parameter_reference#CAL_BARO0_PRIO">CAL_BAROn_PRIO</a>, <a href="./../advanced_config/parameter_reference#CAL_MAG0_PRIO">CAL_MAGn_PRIO</a>, where <code>n</code> is the instance number of the IMU component (0, 1, etc.).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In most cases the external IMU is the highest-numbered. Ви можете отримати список доступних компонентів IMU, використовуючи <a href="./../middleware/uorb#uorb-top-command"><code>uorb top -1</code></a>, ви можете відрізняти їх за допомогою команди <a href="./../modules/modules_command#listener"><code>listener</code></a> та розглядаючи дані чи просто швидкості.</p><p>За потреби ви можете перевірити <a href="./../advanced_config/parameter_reference#CAL_GYRO0_ID">CAL_GYROn_ID</a>, щоб побачити ідентифікатор пристрою. Пріоритет становить 0-255, де 0 абсолютно вимкнено, а 255 - найвищий пріоритет.</p></div></li></ul></li></ol><p>:::</p><pre><code> ::: warning
 When configuring both Inertial Labs and Pixhawk sensors to have non-zero priority, if the selected sensor is errored (timeout), it can change during operation without being notified.
 In this case, MAVLink messages will be updated with the newly selected sensor.

 If you don&#39;t want to have this fallback mechanism, you must disable unwanted sensors.
</code></pre><p>:::</p><ol start="5"><li>Перезавантажте PX4.</li></ol><p>Після активації модуль буде виявлено при завантаженні.</p><h2 id="inertial-labs-sensor-configuration" tabindex="-1">Inertial Labs Sensor Configuration <a class="header-anchor" href="#inertial-labs-sensor-configuration" aria-label="Permalink to &quot;Inertial Labs Sensor Configuration&quot;">​</a></h2><p>Perform sensor configuration according to the Interface Control Document (ICD) that comes with each device. The sensor-configuration software allows you to set the baurate and the data format, and you can also adjust the orientation axes if the sensor wasn&#39;t oriented in the normal way. This process is usually short and takes a few minutes, depending on the sensor and the installation conditions on the vehicle.</p><h2 id="опубліковані-дані" tabindex="-1">Опубліковані дані <a class="header-anchor" href="#опубліковані-дані" aria-label="Permalink to &quot;Опубліковані дані&quot;">​</a></h2><p>These uORB topics are published:</p><ul><li><a href="./../msg_docs/SensorAccel">sensor_accel</a></li><li><a href="./../msg_docs/SensorGyro">датчик_гіроскопа</a></li><li><a href="./../msg_docs/SensorMag">sensor_mag</a></li><li><a href="./../msg_docs/SensorBaro">sensor_baro</a></li><li><a href="./../msg_docs/SensorGps">sensor_gps</a></li></ul><p>If enabled as an external INS, publishes:</p><ul><li><a href="./../msg_docs/VehicleLocalPosition">vehicle_local_position</a></li><li><a href="./../msg_docs/VehicleGlobalPosition">vehicle_global_positon</a></li><li><a href="./../msg_docs/VehicleAttitude">vehicle_attitude</a></li><li><a href="./../msg_docs/EstimatorStatus">estimator_status</a></li><li><a href="./../msg_docs/EstimatorStatusFlags">estimator_status_flags</a></li></ul><p>If enabled as external sensor only:</p><ul><li><code>external_ins_local_position</code></li><li><code>external_ins_global_position</code></li><li><code>external_ins_attitude</code></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Опубліковані теми можна переглянути за допомогою команди <code>listener</code>.</p></div>`,38)])])}const m=r(n,[["render",s]]);export{_ as __pageData,m as default};
